// =============================================================================
// API
// =============================================================================

pub const Parser = if (@hasDecl(lang, "Parser")) lang.Parser else BaseParser;

/// Parse a whole tokens with a new `Parser`. The caller owns
/// `result.parser` and must `deinit()` it when done with the tree.
pub fn parseTokens(allocator: std.mem.Allocator, source: []const u8) !struct { parser: Parser, sexp: Sexp } {
    var p = Parser.init(allocator, source);
    errdefer p.deinit();
    const sexp = try p.parseTokens();
    return .{ .parser = p, .sexp = sexp };
}
